input.sparql:
SELECT ?zone ?sensor ?point WHERE {
  ?zone a brick:Zone .
  FILTER (?zone IN (ref:Core_ZN, ref:Perimeter_ZN_1, ref:Perimeter_ZN_2))
  ?sensor brick:hasPrimaryPoint ?point ;
          ref:hasTimeseriesId ?tsid ;
          brick:isTypeOf ?zone .
  ?sensor a brick:ElectricPowerSensor .
}

SELECT ?z ?s WHERE {
  ?z a brick:Zone .
  ?s brick:isTypeOf ?z .
  ?s a brick:Sensor .
  ?s ref:hasTimeseriesId ?ts .
}

